INSERT INTO bullet (id, entry_id, text, sort_order) VALUES
(1, 1, 'Conduct provenance investigations on individual objects and full acquisition catalogues, analyzing trade routes, import and export records, and antiquities law across multiple regions and historical periods, including navigating both physical and digital archives.', 1),
(2, 1, 'Support active NAGPRA cases in collaboration with Hopi and Pekuakamiulnuatsh (Innu) communities, including drafting and organizing appendices for repatriation proposals submitted to internal review committees and federal authorities.', 2),
(3, 1, 'Maintain confidential documentation regarding affiliated Tribal Nations and descendant communities within the EMu collections management system; produce Crystal Reports and structured object lists to identify repatriation-eligible objects and ancestors and flag materials for review.', 3),
(4, 1, 'Designed a custom PDF converter and integrated an AI-assisted workflow for transcription and translation of mixed French and English handwritten archival documents from Edward Ayre and other substantial accession files, reducing manual processing time on key case files for the Egypt and Nubia exhibit.', 4),
(8, 2, 'Conduct qualitative interviews with professors, students, and educational workers in Gaza documenting academic life under siege.', 1),
(9, 2, 'Author short-form public-facing articles synthesizing topics introduced in our interviews and providing historical context.', 2),
(10, 2, 'Build and maintain a comprehensive historical timeline of scholasticide in Gaza, integrating testimony, news reporting, and scholarly analysis.', 3),
(11, 2, 'Manage editorial workflow, source verification, and archival coordination for the project''s public platform; contribute to website design and organization in WordPress.', 4),
(13, 3, 'Designed a long-term framework for digitizing the archives of small, immigrant, and minority religious institutions in Chicago, including workflow planning and metadata structure design.', 1),
(14, 3, 'Compiled and curated an annotated research library and bibliography to inform the project''s preservation strategy.', 2),
(15, 4, 'Supported research on gender inclusive models of affordable housing and their intersections with mental health, disability justice, and domestic violence prevention, with focus on POC and trans housing-insecure populations in Canada and the United States.', 1),
(16, 4, 'Conducted literature reviews, prepared conference presentations, and copyedited academic publications.', 2),
(17, 5, 'Led weekly discussion sections for a foundational undergraduate survey course; developed and delivered original lesson plans on visual analysis, the anthropology of art history, and contextual interpretation.', 1),
(18, 5, 'Held extensive office hours providing individualized writing support, conceptual clarification, and academic guidance.', 2),
(19, 5, 'Completed all grading for my discussion section across every assignment and exam on schedule, and proctored exams and quizzes.', 3),
(20, 6, 'Provide post-release support and court accompaniment for incarcerated Muslims; serve as liaison between defense attorneys, family members, and BBO staff to coordinate emergency funding disbursement.', 1),
(21, 6, 'Cleaned and standardized four years of intake and participant engagement data (2018–present) across four organizational spreadsheets using Python (pandas, NumPy, matplotlib) in Jupyter Notebooks; produced a report identifying data gaps and authored a follow-up recommendations report on best practices for ongoing data collection.', 2),
(22, 6, 'Co-facilitate a weekly online interfaith Seerah study group; developing a community education curriculum on Islam and abolition.', 3),
(23, 7, 'Directed national communications strategy across Instagram, Facebook, Twitter, and TikTok; authored and edited the monthly national newsletter for several thousand subscribers.', 1),
(24, 7, 'Managed bank accounts, coordinated fundraising, and documented expenditures for the national accounting team; supported legal affiliates with research memos and fundraising documentation.', 2),
(25, 7, 'Oversaw internal communications between regional chapters and national leadership across time zones; led national recruitment and advised chapters on internal strategy and mediation.', 3),
(26, 7, 'Coordinated with international and domestic coalition partners, including the production of comprehensive reports for international legal cases addressing humanitarian violations in Palestine.', 4),
(27, 8, 'Co-founded a community-led project focused on self-determination, digital security, and grassroots infrastructure.', 1),
(28, 8, 'Led programming including cybersecurity trainings, street medic courses, mental health workshops, and youth engagement events.', 2),
(29, 8, 'Collected and archived oral histories of displacement of the Palestinian diaspora in Chicago.', 3),
(30, 9, 'Wrote and managed federal grant application cycles for the Salwa Food Pantry; reviewed annual budgets, interpreted tax returns and financial statements, and advised on budget presentation for funders.', 1),
(31, 9, 'Rebuilt organizational documentation systems and established long-term reporting relationships with federal and private funders.', 2),
(32, 9, 'Managed federal grant compliance and reporting for the FEMA Non-Profit Security Grant, securing $200,000 in grant funding for the organization to improve physical and cyber security.', 3),
(33, 10, 'Lobbied at the Illinois State Capitol and coordinated student testimony in support of the Mental Health Early Action on Campus Act (HB2152, signed August 2019).', 1),
(34, 10, 'Registered 300+ students to vote at UIC over a five-month period, in coalition with Chicago Votes and Power to the Polls', 2),
(35, 10, 'Delivered presentations on higher education access and mental health advocacy across the Chicagoland area.', 3),
(36, 11, 'Founded a grassroots sexual health and gender education initiative in collaboration with Planned Parenthood Southeast.', 1),
(37, 11, 'Developed and taught the first comprehensive sexual education program at Academe of the Oaks High School in Atlanta.', 2),
(38, 12, 'Co-authored policy materials supporting the Illinois Mental Health Early Action on Campus Act.', 1),
(39, 12, 'Supported anti-gentrification and labor organizing campaigns on campus.', 2),
(40, 13, 'Organized undergraduate solidarity actions during GEO''s three-week strike (March 19 – April 5, 2019), including walkouts and support pickets.', 1),
(41, 13, 'Conducted contract research identifying leverage points for the bargaining team; the GEO settlement secured wage increases, fee relief, and stronger appointment transparency provisions.', 2),
(42, 15, 'MSM STD outreach research and report writing and editing for internal publication.', 1),
(43, 16, 'Identify and document recurring error classes across complete sections to support consistency standards across the proofreading team and inform downstream correction passes.', 1),
(44, 16, 'Review and submit completed sections through the project''s editorial portal on a defined production schedule.', 2),
(45, 17, 'Trained in network architecture, covering the chronology and evolution of internet protocols, distributed-systems design patterns, and failure modes; apply the material directly to independent project white-lotus.', 1),
(46, 17, 'Draft service contracts and design invoicing and client documentation systems.', 2),
(47, 30, 'Thesis in progress: "Restitution and the State: Repatriation, Repentance, and the Limits of State-Led Repair." Advised by Prof. Alireza Doostdar.', 1),
(48, 30, 'Comparative study of NAGPRA and the 1952 Luxembourg Agreement, drawing on Maimonidean teshuvah, Islamic tawba, and theorists of state-formation.', 2),
(49, 31, 'Senior thesis: "Let Them Return Home: Creating Culturally Conscious NAGPRA Reform Prioritizing Indigenous Sovereignty and Spiritual Belief." Advised by Dr. Vincent LaMotta.', 1);
